<?php
declare(strict_types=1);
function crmPeriod(array $q): array {
 $tz=new DateTimeZone('Europe/Kyiv');$today=new DateTimeImmutable('today',$tz);$period=$q['period']??'today';$start=match($period){'today'=>$today,'yesterday'=>$today->modify('-1 day'),'7d'=>$today->modify('-6 days'),'30d'=>$today->modify('-29 days'),'custom'=>DateTimeImmutable::createFromFormat('!Y-m-d',(string)($q['from']??''),$tz),default=>false};$end=$period==='yesterday'?$today:$today->modify('+1 day');if($period==='custom'){$last=DateTimeImmutable::createFromFormat('!Y-m-d',(string)($q['to']??''),$tz);if(!$last)throw new CrmError('INVALID_DATE');$end=$last->modify('+1 day');}if(!$start||$start>=$end||$end->getTimestamp()-$start->getTimestamp()>366*86400)throw new CrmError('INVALID_PERIOD');return [$start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),$end->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s')];
}
function crmFinancialFacts(PDO $db,array $q): array {
 [$from,$to]=crmPeriod($q);$extra='';$args=[];if(!empty($q['manager'])){$extra.=' AND EXISTS(SELECT 1 FROM rubizh_order_assignments a WHERE a.order_id=o.id AND a.staff_id=?)';$args[]=$q['manager'];}if(!empty($q['supplier'])){$extra.=' AND EXISTS(SELECT 1 FROM rubizh_order_fulfillment_lines f WHERE f.order_id=o.id AND f.supplier_code=?)';$args[]=$q['supplier'];}
 $income=crmQuery($db,"SELECT i.order_id,i.amount,ev.paid_at FROM rubizh_mono_invoices i JOIN rubizh_customer_orders o ON o.id=i.order_id JOIN(SELECT invoice_id,MIN(created_at) paid_at FROM rubizh_mono_events WHERE status='success' GROUP BY invoice_id) ev ON ev.invoice_id=i.invoice_id WHERE ev.paid_at>=? AND ev.paid_at<? $extra",[$from,$to,...$args]);
 $manual=crmQuery($db,"SELECT o.id order_id,ROUND(o.total*100) amount,c.confirmed_at paid_at FROM rubizh_customer_orders o JOIN rubizh_np_order_confirmations c ON c.order_id=o.id WHERE c.payment_proof<>'' AND c.confirmed_at>=? AND c.confirmed_at<? AND NOT EXISTS(SELECT 1 FROM rubizh_mono_invoices mi WHERE mi.order_id=o.id AND mi.status IN ('success','reversed')) $extra",[$from,$to,...$args]);
 $refund=(int)crmOne($db,"SELECT COALESCE(SUM(r.amount),0) amount FROM rubizh_refund_operations r JOIN rubizh_customer_orders o ON o.id=r.order_id WHERE r.status='success' AND r.updated_at>=? AND r.updated_at<? $extra",[$from,$to,...$args])['amount'];
 $legacy=(int)crmOne($db,"SELECT COALESCE(SUM(i.amount),0) amount FROM rubizh_mono_invoices i JOIN rubizh_customer_orders o ON o.id=i.order_id WHERE i.refund_status='success' AND i.updated_at>=? AND i.updated_at<? AND NOT EXISTS(SELECT 1 FROM rubizh_refund_operations r WHERE r.invoice_id=i.id) $extra",[$from,$to,...$args])['amount'];
 $all=[...$income,...$manual];$paid=array_sum(array_column($all,'amount'));$paidOrders=count(array_unique(array_column($all,'order_id')));$daily=[];foreach($all as $fact){$date=(new DateTimeImmutable($fact['paid_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Europe/Kyiv'))->format('Y-m-d');$daily[$date]=($daily[$date]??0)+(int)$fact['amount'];}ksort($daily);
 return ['paid_orders'=>$paidOrders,'paid_revenue'=>$paid/100,'refunds'=>($refund+$legacy)/100,'net_revenue'=>($paid-$refund-$legacy)/100,'average_paid_order'=>$paidOrders?$paid/$paidOrders/100:0,'daily'=>array_map(fn($date,$amount)=>['date'=>$date,'amount'=>$amount/100],array_keys($daily),$daily)];
}
function crmReports(PDO $db,array $q,array $actor): array {
 [$from,$to]=crmPeriod($q);$counts=crmOne($db,"SELECT COUNT(*) orders_created,SUM(o.pim_order_state='WAITING_CONFIRMATION' OR o.status='new') confirmation_queue,SUM(o.status IN ('delivered','completed')) delivered FROM rubizh_customer_orders o LEFT JOIN rubizh_order_assignments a ON a.order_id=o.id WHERE o.created_at>=? AND o.created_at<?".(!empty($q['manager'])?' AND a.staff_id=?':'').(!empty($q['supplier'])?' AND EXISTS(SELECT 1 FROM rubizh_order_fulfillment_lines f WHERE f.order_id=o.id AND f.supplier_code=?)':''),[$from,$to,...(!empty($q['manager'])?[$q['manager']]:[]),...(!empty($q['supplier'])?[$q['supplier']]:[])]);$returnWhere='';$returnArgs=[$from,$to];if(!empty($q['manager'])){$returnWhere.=' AND EXISTS(SELECT 1 FROM rubizh_order_assignments a WHERE a.order_id=r.order_id AND a.staff_id=?)';$returnArgs[]=$q['manager'];}if(!empty($q['supplier'])){$returnWhere.=' AND EXISTS(SELECT 1 FROM rubizh_order_fulfillment_lines f WHERE f.order_id=r.order_id AND f.supplier_code=?)';$returnArgs[]=$q['supplier'];}$returns=(int)crmOne($db,'SELECT COUNT(*) n FROM rubizh_returns r WHERE r.created_at>=? AND r.created_at<?'.$returnWhere,$returnArgs)['n'];$financial=crmCan($actor,'report.view')?crmFinancialFacts($db,$q):null;return ['period'=>['from'=>$from,'to'=>$to,'timezone'=>'Europe/Kyiv'],'metrics'=>$counts+['returns'=>$returns],'financial'=>$financial];
}
function crmDashboard(PDO $db,array $actor): array {
 $today=crmReports($db,['period'=>'today'],$actor);$counts=crmOne($db,"SELECT COUNT(*) total,SUM(o.status='new' OR o.pim_order_state='WAITING_CONFIRMATION') confirmation,SUM(o.payment_status IN ('pending','failed') AND o.status IN ('confirmed','processing')) waiting_payment,SUM(o.payment_status='paid' AND o.status IN ('confirmed','processing')) paid_to_ship,SUM(o.status IN ('shipped','partially_shipped')) transit,SUM(o.status IN ('returned','partially_returned') OR o.status='cancelled' AND o.payment_status='paid') problems FROM rubizh_customer_orders o");$action=crmOrders($db,['limit'=>8,'sort'=>'date','direction'=>'asc','view'=>'confirmation'],$actor);$problems=crmOrders($db,['limit'=>5,'view'=>'problems'],$actor);
 return ['today'=>$today,'counts'=>$counts,'requires_action'=>$action['rows'],'problems'=>$problems['rows']];
}
function crmAuditRows(PDO $db,array $q,array $actor): array {
 crmPermit($actor,'audit.view');$p=crmPage($q);$where=['1=1'];$args=[];foreach(['entity','entity_id','actor_id'] as $k)if(($q[$k]??'')!==''){$where[]="a.$k=?";$args[]=$q[$k];}
 $base="SELECT CONCAT('staff:',id) id,actor_id,actor_role,source,entity,entity_id,action,before_json,after_json,reason,request_id,created_at FROM rubizh_staff_audit";
 // ТЗ 7.13: OWNER — everything (CRM + SITE domain audit); ACCOUNTANT — payment records; MANAGER — own orders only.
 $domain=" UNION ALL SELECT CONCAT('domain:',id),actor_id,actor_role,source,'order',CAST(order_id AS CHAR),action,before_json,after_json,reason,'',created_at FROM rubizh_order_audit";
 if($actor['role']==='OWNER')$base.=$domain;
 elseif($actor['role']==='ACCOUNTANT'){$base.=$domain;$where[]="(a.action LIKE 'payment.%' OR a.action LIKE 'export.%' AND a.actor_id=?)";$args[]=$actor['id'];}
 else{$where[]="a.entity='order' AND a.action NOT LIKE 'payment.%' AND EXISTS(SELECT 1 FROM rubizh_order_assignments asg WHERE asg.order_id=CAST(a.entity_id AS UNSIGNED) AND asg.staff_id=?)";$args[]=$actor['id'];}
 $where=implode(' AND ',$where);$total=(int)crmOne($db,'SELECT COUNT(*) total FROM ('.$base.') a WHERE '.$where,$args)['total'];$rows=crmQuery($db,'SELECT a.*,u.name actor FROM ('.$base.') a LEFT JOIN rubizh_staff_users u ON u.id=a.actor_id WHERE '.$where." ORDER BY a.created_at DESC,a.id DESC LIMIT {$p['limit']} OFFSET {$p['offset']}",$args);foreach($rows as &$r){$r['old']=json_decode($r['before_json'],true);$r['new']=json_decode($r['after_json'],true);unset($r['before_json'],$r['after_json']);}return ['rows'=>$rows,'pagination'=>['page'=>$p['page'],'limit'=>$p['limit'],'total'=>$total,'pages'=>(int)ceil($total/$p['limit'])]];
}
function crmList(PDO $db,string $entity,array $q): array {
 $p=crmPage($q);$table=['payments'=>'rubizh_mono_invoices','shipments'=>'rubizh_order_shipments','returns'=>'rubizh_returns'][$entity]??null;if(!$table)throw new CrmError('NOT_FOUND',404);$where=['1=1'];$args=[];
 if(!empty($q['q'])){$mail=($q['_contact']??true)===true; // stage 4.1: no e-mail search without order.search.contact
  $where[]="(o.order_number LIKE ? ESCAPE '!'".($mail?" OR o.email LIKE ? ESCAPE '!'":'').($entity==='shipments'?" OR e.tracking_number LIKE ? ESCAPE '!'":'').')';$args=[crmLike($q['q'])];if($mail)$args[]=crmLike($q['q']);if($entity==='shipments')$args[]=crmLike($q['q']);}
 if(!empty($q['state'])){$where[]=($entity==='returns'?'e.state':'e.status').'=?';$args[]=$q['state'];}$where=implode(' AND ',$where);$total=(int)crmOne($db,"SELECT COUNT(*) n FROM $table e JOIN rubizh_customer_orders o ON o.id=e.order_id WHERE $where",$args)['n'];$rows=crmQuery($db,"SELECT e.*,o.order_number,o.payment_status,o.pim_payment_state,o.email FROM $table e JOIN rubizh_customer_orders o ON o.id=e.order_id WHERE $where ORDER BY e.id DESC LIMIT {$p['limit']} OFFSET {$p['offset']}",$args);return ['rows'=>$rows,'pagination'=>['page'=>$p['page'],'limit'=>$p['limit'],'total'=>$total,'pages'=>(int)ceil($total/$p['limit'])]];
}
function crmStaffSave(PDO $db,array $actor,array $b,?string $id=null): array {
 crmPermit($actor,'staff.manage');$reason=shopFinancialReason((string)($b['reason']??''));$role=crmRoleAlias((string)($b['role']??''));$email=mb_strtolower(trim((string)($b['email']??'')));$name=trim((string)($b['name']??''));$enabled=($b['enabled']??true)===true;$password=$b['password']??null;if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($name)<2||mb_strlen($name)>120||!in_array(crmRoleAlias($role),CRM_ROLES,true)||$password!==null&&(!is_string($password)||strlen($password)<12||strlen($password)>72)||$id===null&&$password===null)throw new CrmError('INVALID_STAFF');if(is_string($password))crmPasswordPolicy($password,$email); // R4-09
 return crmTransaction($db,function()use($db,$actor,$b,$id,$role,$email,$name,$enabled,$password,$reason){$old=$id?crmOne($db,'SELECT id,email,name,role,enabled,session_version FROM rubizh_staff_users WHERE id=? FOR UPDATE',[$id]):null;if($id&&!$old)throw new CrmError('NOT_FOUND',404);if($old&&($old['role']==='OWNER')&&(!$enabled||$role!=='OWNER')){$owners=crmQuery($db,"SELECT id FROM rubizh_staff_users WHERE role='OWNER' AND enabled=1 FOR UPDATE");if(count($owners)<=1)throw new CrmError('LAST_OWNER_REQUIRED',409);}if($old&&(int)($b['session_version']??0)!==(int)$old['session_version'])throw new CrmError('STALE_ORDER',409);$id??=bin2hex(random_bytes(16));if(!$old)$db->prepare('INSERT INTO rubizh_staff_users(id,email,name,role,enabled,password_hash,created_at,updated_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute([$id,$email,$name,$role,(int)$enabled,crmPasswordHash($password)]);else{$sql='UPDATE rubizh_staff_users SET email=?,name=?,role=?,enabled=?,session_version=session_version+1,updated_at=UTC_TIMESTAMP()'.($password!==null?',password_hash=?':'').' WHERE id=?';$db->prepare($sql)->execute([$email,$name,$role,(int)$enabled,...($password!==null?[crmPasswordHash($password)]:[]),$id]);}crmAudit($db,$actor,'staff',$id,'staff.update',$old??[],['email'=>$email,'name'=>$name,'role'=>$role,'enabled'=>$enabled,'password_changed'=>$password!==null],$reason);return crmOne($db,'SELECT id,email,name,role,enabled,session_version FROM rubizh_staff_users WHERE id=?',[$id]);});
}
